import React, { useContext, useEffect, useId, useRef, useState } from 'react';
import { Link } from 'react-router-dom';
import { FiChevronDown, FiMoreHorizontal } from 'react-icons/fi';
import logo from '../assets/logo.png';
import { AuthContext } from '../context/AuthContext';
import './console.css';

// The signed-in console: one slim bar (brand, where you are, your account) and the work area.
// It replaces the marketing header and footer on the workspace pages, so the page starts with its content.
export default function Console({ crumbs = [], children }) {
  return (
    <div className="cs">
      <header className="cs-bar">
        <Link to="/" className="cs-brand" aria-label="Plotune home">
          <img src={logo} alt="" />
          <span translate="no">Plotune</span>
        </Link>
        <nav className="cs-crumbs" aria-label="Breadcrumb">
          {crumbs.map((crumb, index) => (
            <React.Fragment key={crumb.to || crumb.label}>
              <span className="cs-crumbs__sep" aria-hidden="true">/</span>
              {crumb.to && index < crumbs.length - 1
                ? <Link to={crumb.to}>{crumb.label}</Link>
                : <span aria-current="page" translate={index ? 'no' : undefined}>{crumb.label}</span>}
            </React.Fragment>
          ))}
        </nav>
        <AccountMenu />
      </header>
      {children}
    </div>
  );
}

function AccountMenu() {
  const { user, logout } = useContext(AuthContext) || {};
  const name = user?.email || user?.username || 'Account';
  return (
    <Menu
      className="cs-account"
      label={`Account: ${name}`}
      align="end"
      button={(
        <>
          <span className="cs-avatar" aria-hidden="true">{name.slice(0, 1).toUpperCase()}</span>
          <span className="cs-account__name" translate="no">{name}</span>
          <FiChevronDown aria-hidden="true" />
        </>
      )}
    >
      {(close) => (
        <>
          <Link role="menuitem" to="/dashboard" onClick={close}>Dashboard</Link>
          <Link role="menuitem" to="/profile" onClick={close}>Profile</Link>
          {logout && <button type="button" role="menuitem" className="cs-menu__last" onClick={() => { close(); logout(); }}>Log out</button>}
        </>
      )}
    </Menu>
  );
}

// A small menu under its button. Closes on Escape, on a click outside and after a choice; arrow keys move between items.
export function Menu({ label, button, children, className = '', align = 'start' }) {
  const [open, setOpen] = useState(false);
  const root = useRef(null);
  const id = useId();
  const items = () => [...(root.current?.querySelectorAll('[role="menu"] [role="menuitem"]') || [])];
  useEffect(() => {
    if (!open) return undefined;
    items()[0]?.focus();
    const onPointer = (event) => { if (!root.current?.contains(event.target)) setOpen(false); };
    document.addEventListener('mousedown', onPointer);
    return () => document.removeEventListener('mousedown', onPointer);
  }, [open]);
  const close = () => { setOpen(false); root.current?.querySelector('.cs-menu__button')?.focus(); };
  const onKeyDown = (event) => {
    if (!open) return;
    if (event.key === 'Escape') { event.stopPropagation(); close(); return; }
    if (event.key !== 'ArrowDown' && event.key !== 'ArrowUp') return;
    event.preventDefault();
    const all = items();
    const at = all.indexOf(document.activeElement);
    all[(at + (event.key === 'ArrowDown' ? 1 : all.length - 1)) % all.length]?.focus();
  };
  return (
    <div className={`cs-menu ${className}`.trim()} ref={root} onKeyDown={onKeyDown}>
      <button type="button" className="cs-menu__button" aria-haspopup="menu" aria-expanded={open} aria-controls={open ? id : undefined} aria-label={label} onClick={() => setOpen((value) => !value)}>
        {button}
      </button>
      {open && <div id={id} className="cs-menu__pop" role="menu" data-align={align}>{children(close)}</div>}
    </div>
  );
}

// The "more" menu at the end of a row (rename, delete).
export const RowMenu = ({ label, children }) => (
  <Menu className="cs-rowmenu" label={label} align="end" button={<FiMoreHorizontal aria-hidden="true" />}>{children}</Menu>
);

// A card of the console: a title, one optional action at its right, then the content.
export function Card({ title, headingId, action, wide = false, children }) {
  return (
    <section className={`cs-card${wide ? ' cs-card--wide' : ''}`} aria-labelledby={headingId}>
      <header className="cs-card__head">
        <h2 id={headingId}>{title}</h2>
        {action}
      </header>
      {children}
    </section>
  );
}

// The square mark of a workspace or a person: its first letter on a tint chosen from the name, so it stays the same everywhere.
const TINTS = ['#e8eef6', '#e6f1ec', '#f4ece0', '#efe9f6', '#f6e9ec', '#e5f0f3'];
const INKS = ['#3d5a80', '#2f6b4f', '#8a5a1c', '#62468c', '#96405a', '#2c6373'];
export function Mark({ name = '', round = false, size = 40 }) {
  let sum = 0;
  for (const character of String(name)) sum = (sum + character.codePointAt(0)) % TINTS.length;
  return (
    <span className={`cs-mark${round ? ' cs-mark--round' : ''}`} aria-hidden="true" style={{ width: size, height: size, background: TINTS[sum], color: INKS[sum], fontSize: Math.round(size * 0.42) }}>
      {String(name).trim().slice(0, 1).toUpperCase() || '·'}
    </span>
  );
}
